// @pit: {"label": "Rewrite the 🔧 and ↳ rows in how-it-works.md and add CONTRIBUTING row"}
async ({ workspace: { search, edit } }) => {
  const how = await search("^\\| `(🔧|↳ ✓)", { path: "docs/how-it-works.md", regex: true });
  const [h1, h2] = how.matches;
  const con = await search("[`src/tool-env.ts`]", { path: "CONTRIBUTING.md" });
  const tool = "A tool can show its own text instead (see [Show tool calls in the workflow log](extensions.md#show-tool-calls-in-the-workflow-log))";
  await edit("docs/how-it-works.md", { revision: h1.revision, changes: [
    { kind: "replace", start: h1.anchor, content: `| \`🔧\` | A tool call, when it starts. For a call with a label, such as a pit program with \`// @pit: {"label": "..."}\` as its first line, only the label. For other calls, the tool and its main argument (the command or the path). For a script of more than one line, the first line and the number of other lines. ${tool} | |` },
    { kind: "replace", start: h2.anchor, content: `| \`↳ ✓\` or \`↳ ✗ failed\` | The end of a tool call: how long it took, and how many lines of output it gave. ${tool} | The arguments (a pit program without its \`// @pit:\` line, and long JSON values indented), and the last 30 lines of output |` },
  ] });
  await edit("CONTRIBUTING.md", { revision: con.matches[0].revision, changes: [{ kind: "insertAfter", anchor: con.matches[0].anchor, content: "| [`src/tool-presentation.ts`](src/tool-presentation.ts) | The `present` field of a tool: how the workflow log shows its calls, checked |" }] });
  const after = await search("^\\| `(🔧|↳ ✓)", { path: "docs/how-it-works.md", regex: true });
  return after.matches.map(m => m.text);
}
